                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.snitch_final_get_put_away_new AS select _airbyte_data:\"EAN\"::STRING as EAN ,_airbyte_data:\"Name\"::STRING as NAME ,_airbyte_data:\"Type\"::STRING as TYPE ,_airbyte_data:Created::TIMESTAMP as CREATED ,_airbyte_data:Updated::TIMESTAMP as UPDATED ,_airbyte_data:\"Category\"::STRING as \"CATEGORY\" ,_airbyte_data:\"Batch Code\"::STRING as \"Batch Code\" ,_airbyte_data:\"Created By\"::STRING as \"Created By\" ,_airbyte_data:\"Shelf Code\"::STRING as \"Shelf Code\" ,_airbyte_data:\"Putaway Code\"::STRING as \"Putaway Code\" ,_airbyte_data:\"Inventory Type\"::STRING as \"Inventory Type\" ,_airbyte_data:\"Total Quantity\"::INTEGER as \"Total Quantity\" ,_airbyte_data:\"Warehouse Name\"::STRING as \"Warehouse Name\" ,_airbyte_data:\"Putaway Item Id\"::STRING as \"Putaway Item Id\" ,_airbyte_data:\"Item Type skuCode\"::STRING as \"Item Type skuCode\" ,_airbyte_data:\"Putaway qc Comment\"::STRING as \"Putaway qc Comment\" ,_airbyte_data:\"Putaway Status Code\"::STRING as \"Putaway Status Code\" ,_airbyte_data:\"Bad inventory Reason\"::STRING as \"Bad inventory Reason\" ,_airbyte_data:\"Putaway Item Status Code\"::STRING as \"Putaway Item Status Code\" ,_airbyte_data:\"Putaway Completed Quantity\"::INTEGER as \"Putaway Completed Quantity\" from snitch_db.maplemonk._airbyte_raw_snitch_final_get_put_away_new QUALIFY ROW_NUMBER () OVER (PARTITION BY \"Putaway Item Id\",\"Warehouse Name\",\"Putaway Code\",Created ORDER BY _airbyte_data:\"Updated\"::DATE DESC ) = 1 ; CREATE OR REPLACE TABLE snitch_db.maplemonk.putaway_tracking AS SELECT a.\"Putaway Code\", CASE WHEN LOWER(a.\"Created By\") like \'%gopal%\' and lower(a.type) like \'%grn%\' and \"Warehouse Name\" in (\'SAPL-WH1\') and created >= \'2025-04-01\' and created <= \'2025-04-25\' then \'Store Return Inward\' WHEN LOWER(a.\"Created By\") LIKE \'%store%\' THEN \'Store Return Inward\' WHEN LOWER(a.\"Created By\") LIKE \'%return%\' and lower(a.type) like (\'%grn%\')THEN \'WPR Inward\' WHEN LOWER(a.type) LIKE \'%grn%\' and ( lower(a.\"Created By\") like \'%hemant%\' or lower(a.\"Created By\") like \'%adava%\' or lower(a.\"Created By\") like \'%guramm%\' or lower(a.\"Created By\") like \'%divya%\' ) THEN \'New Inward\' WHEN LOWER(a.type) LIKE \'%grn%\' THEN \'New Inward\' WHEN LOWER(a.type) LIKE \'%reverse%\' OR LOWER(a.type) LIKE \'%return%\' THEN \'B2C Return Inward\' WHEN LOWER(a.type) LIKE \'%cancelled%\' OR LOWER(a.type) LIKE \'%picklist%\' THEN \'Putback Activity\' WHEN LOWER(a.type) LIKE \'%shelf%\' THEN \'Audit Activity\' WHEN LOWER(a.type) LIKE \'%gatepass%\' THEN \'Gatepass Activity\' ELSE \'BAU_PT\' END AS final_type, a.type AS putaway_type, a.created::timestamp AS putaway_created, a.updated::timestamp AS putaway_updated, a.updated::date as putaway_completed_date, a.\"Inventory Type\", CAST(a.\"Total Quantity\" AS NUMERIC) AS total_quantity, CAST(a.\"Putaway Completed Quantity\" AS NUMERIC) AS putaway_completed_quantity, CAST(a.\"Total Quantity\" - a.\"Putaway Completed Quantity\" AS NUMERIC) AS pending_qty, a.\"Putaway Status Code\", upper(a.\"Putaway Item Status Code\") as \"Putaway Item Status Code\" , a.\"Bad inventory Reason\", a.\"Warehouse Name\", a.\"Putaway Item Id\", a.\"Item Type skuCode\", a.\"Putaway qc Comment\", a.\"Created By\", a.\"Shelf Code\", c.\"CATEGORY\" AS sku_category, c.sku_group, c.\"SKU_CLASS\" AS class, a.Category, a.EAN, a.NAME AS product_name, a.\"Batch Code\" FROM snitch_db.maplemonk.snitch_final_get_put_away_new AS a LEFT JOIN snitch_db.maplemonk.availability_master_v2 AS c ON upper(LEFT(a.\"Item Type skuCode\", LENGTH(a.\"Item Type skuCode\") - CHARINDEX(\'-\', REVERSE(a.\"Item Type skuCode\")))) = CASE WHEN POSITION(\'-\' IN c.sku_group) > 0 AND LEFT(c.sku_group, 2) = \'SH\' THEN UPPER(SPLIT_PART(c.sku_group, \'-\', 1)) WHEN POSITION(\'-\' IN c.sku_group) > 0 THEN UPPER(SPLIT_PART(c.sku_group, \'-\', 1)) || \'-\' || UPPER(SPLIT_PART(c.sku_group, \'-\', 2)) ELSE UPPER(c.sku_group) END WHERE a.updated::date >= \'2024-04-01\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.gs_floor_pendency1 AS ( SELECT \"WAREHOUSE\", status as reason, \"SAPL-WH1\" as inward_type, \"SAPL-WH2\" as source, store_returns::integer as quantity, SAPL_EMIZA as remark, \"SAPL-SR\" as dummy_1, \"TOTAL\" as dummy_2 FROM SNITCH_DB.MAPLEMONK.GS_FLOOR_PENDENCY ); CREATE OR REPLACE TABLE snitch_db.maplemonk.rts_summary_wh AS WITH rts AS ( SELECT TRY_TO_DATE(entry_date, \'DD/MM/YYYY\') AS date, sku AS style, description, repeat, new_style, CAST(REPLACE(online_qty, \',\', \'\') AS INT) as online_qty, vendor, rts_status, TRY_TO_DATE(expected_delivery_date, \'DD/MM/YYYY\') AS expected_delivery_date, warehouse, class, ars, remark, photoshoot_received, qc_status, qc_report, costing, logic_po, pl_and_cm_receving_date, fabric_dc, work_order, mini_marker, invoice FROM snitch_db.maplemonk.gs_onlinegoods_rts ) SELECT rts.*, am.category, am.product_name, am.price, am.total_eoq, am.available_units, am.sku_class, am.sellable_inventory, am.status, md.final_status, case when logic_po is null and (lower(photoshoot_received) not in (\'yes\') or photoshoot_received is null) then \'Shoot + PO Pending\' when logic_po is null then \'PO Pending\' when lower(photoshoot_received) not in (\'yes\') or photoshoot_received is null then \'Shoot Pending\' else null end as RCA, case when repeat = \'YES\' THEN \'REPEAT\' when md.final_status = \'INWARD_NOT_DONE\' then \'CATALOGUED\' when rts.style in (\'4MST2687-01\',\'4MST2686-01\',\'4MST2685-01\',\'4MSS4031-01\',\'4MST2727-02\',\'4MST2727-01 \',\'4MSK8702-01\',\'4MSK8701-01\',\'4MOS1005-02\',\'4MOS1005-01\',\'4MSD4003-03\',\'4MSD4003-02\',\'4MSD4003-01\',\'4MSR5297-02\',\'4MSR5297-01 \',\'4MSR5299-01\',\'4MSR5298-01\',\'4MSS3990-01\',\'4MSW9080-02\',\'4MSW9080-01\',\'4MSS3989-01\',\'4MSS3988-01\',\'4MST2684-02\',\'4MST2684-01\') THEN \'NEW COLLECTION\' when rts.style like \'%4MLX%\' then \'LUXE\' when rts.style in (\'4MSS2839-04\',\'4MSS2839-03\',\'4